draw(a--b--c--d--e--f--a);
dot(a); dot(b); dot(c); dot(d); dot(e); dot(f); dot(g); dot(h); dot(i);
draw(g--h--i--g);
draw(a--d, dashed);
draw(b--e, dashed);
draw(c--f, dashed);
draw((-g)--(-h)--(-i)--(-g), dashed);
label("$A$",a,W);
label("$B$",b,NNW);
label("$C$",c,NNE);
label("$D$",d,E);
label("$E$",e,SSE);
label("$F$",f,SSW);
label("$G$",g,WNW);
label("$H$",h,ENE);
label("$I$",i,S);
[/asy]

